#include <iostream>
#include <string>

class Tree {
private:
    std::string type;      // e.g., "Oak", "Pine"
    std::string color;     // e.g., "green"
    std::string texture;   // e.g., "bark.png"
    int x;                 // position X
    int y;                 // position Y

public:
    Tree(std::string type, std::string color, std::string texture, int x, int y)
        : type(std::move(type)), color(std::move(color)), texture(std::move(texture)), x(x), y(y) {}

    void render() const {
        std::cout << "Rendering " << type << " tree | color: " << color
                   << " texture: " << texture << " at (" << x << "," << y << ")" << std::endl;
    }
};

int main() {
    // Naive approach: every tree gets its own full copy of type/color/texture
    Tree t1("Oak", "green", "bark.png", 100, 200);
    Tree t2("Oak", "green", "bark.png", 300, 150);
    Tree t3("Pine", "darkgreen", "pine.png", 200, 300);

    t1.render();
    t2.render();
    t3.render();

    return 0;
}

// Client asks: "Give me an Oak tree"
// Factory checks cache -> already exists -> returns same Oak object
//
// Client asks again: "Give me an Oak tree"
// Factory checks cache -> returns same Oak object again (not a new one)

// Without Flyweight:
// 50,000 trees = 50,000 full objects in memory
//
// With Flyweight:
// 50,000 trees = 3 shared objects + 50,000 lightweight positions

