#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>

class TreeFlyweight {
public:
    virtual void render(int x, int y) const = 0;
    virtual ~TreeFlyweight() = default;
};

class ConcreteTree : public TreeFlyweight {
private:
    std::string type;
    std::string color;
    std::string texture;

public:
    ConcreteTree(std::string type, std::string color, std::string texture)
        : type(std::move(type)), color(std::move(color)), texture(std::move(texture)) {}

    void render(int x, int y) const override {
        std::cout << "Rendering " << type << " tree [Color: " << color
                   << ", Texture: " << texture << "] at (" << x << "," << y << ")" << std::endl;
    }
};

class TreeFactory {
private:
    std::unordered_map<std::string, std::shared_ptr<TreeFlyweight>> cache;

public:
    std::shared_ptr<TreeFlyweight> getTree(const std::string& type, const std::string& color, const std::string& texture) {
        std::string key = type + color + texture;
        auto it = cache.find(key);
        if (it == cache.end()) {
            auto tree = std::make_shared<ConcreteTree>(type, color, texture);
            cache[key] = tree;
            return tree;
        }
        return it->second;
    }

    int getTreeTypeCount() const {
        return static_cast<int>(cache.size());
    }
};

int main() {
    TreeFactory factory;

    auto oak1 = factory.getTree("Oak", "green", "bark.png");
    auto oak2 = factory.getTree("Oak", "green", "bark.png");

    oak1->render(100, 200);
    oak2->render(300, 150);

    std::cout << "Same object? " << (oak1 == oak2 ? "true" : "false") << std::endl;
    std::cout << "Tree types cached: " << factory.getTreeTypeCount() << std::endl;

    return 0;
}

